// ---------------------------------------------------------------- voices
// {name} is the speaker's name, {guild} the player's guild.
// Each voice: hello (first words), name (the introduction), again (return
// visit), more (after a topic), ask (the interview opens), bye (farewell).

/** Recruits and challengers speak by their personality (src/data/content.js PERSONALITIES). */
export const PERSONALITY_VOICES = {
  Brave: { name: 'I’m {name}. I don’t run, and I don’t ask twice.', again: 'There you are. Got something worth fighting for yet?', more: 'What else?', ask: 'Ask. I’ll answer straight.', bye: 'Until the next fight.' },
  Vain: { name: '{name}. You’ve heard of me, surely. No? You will.', again: 'Back to admire me? Understandable.', more: 'Go on. I’m listening, mostly.', ask: 'Ask away. I improve any story I’m in.', bye: 'Do tell people you met me.' },
  Patient: { name: 'My name is {name}. Sit, if you like. I’m in no hurry.', again: 'You came back. I thought you might.', more: 'Take your time. What else?', ask: 'Ask what you need. We have all evening.', bye: 'Go well. I’ll be here.' },
  Jealous: { name: '{name}. Better than half the names on that ranking board.', again: 'Back again? Did the others turn you down?', more: 'Anything else?', ask: 'Fine. Ask. Just don’t compare me to anyone.', bye: 'Don’t hire someone worse than me.' },
  Merciful: { name: 'I’m {name}. Are you hurt? People usually are, coming in here.', again: 'Good, you’re still in one piece. What can I do?', more: 'What else is on your mind?', ask: 'Of course. Ask me anything.', bye: 'Look after your people.' },
  Obsessive: { name: '{name}. Sorry, I was counting something. Forty-one.', again: 'Ah. You. Where was I? Forty-two.', more: 'Next question?', ask: 'Questions. Good. I like a list.', bye: 'Forty-three. Goodbye.' },
  Cautious: { name: '…{name}. Who’s asking, exactly?', again: 'You again. All right. What is it?', more: 'Something else?', ask: 'Ask. I’ll decide what to answer.', bye: 'Watch the road.' },
  Witty: { name: 'The name’s {name}. Write it down; it looks better in ink.', again: 'Back already? I knew my charm was working.', more: 'And for my next trick?', ask: 'An interview! Do I get to ask questions too?', bye: 'Don’t miss me too loudly.' },
  Honorable: { name: 'I am {name}. Well met, {guild}.', again: 'Well met again, {guild}.', more: 'What else would you ask?', ask: 'Ask freely. You’ll have honest answers.', bye: 'Go with honour.' },
  Restless: { name: '{name}. Is it always this slow in here? I’ve been sitting for an hour.', again: 'Finally, someone interesting. You again.', more: 'Quick, what else?', ask: 'Ask fast. I hate sitting still.', bye: 'Right. Off I go.' },
};

